package com.doctoolkit.controller;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.mock.web.MockMultipartFile; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DocumentControllerTest { @Autowired MockMvc mvc; @Test void convertTxtToPdf() throws Exception { MockMultipartFile f=new MockMultipartFile("file","a.txt","text/plain","Hello DocToolkit".getBytes()); mvc.perform(multipart("/convert").file(f).param("targetFormat","pdf")).andExpect(status().isOk()).andExpect(header().string("Content-Disposition", org.hamcrest.Matchers.containsString("attachment"))); } }
